-- Bootstrap 1 (tracker C7). Objects created by hand on the hosted production database and needed from 20261001160000_core_learning_engine.sql on.
-- Each is created ONLY IF MISSING: on production nothing changes; on an empty database this supplies them. Generated by scripts/release/build_bootstrap.py.
begin;
set local check_function_bodies = off;

do $boot$ begin if to_regprocedure('public.qb_can_manage_class(uuid)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_can_manage_class(p_class_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$select quizbox_market.class_allowed(p_class_id) and coalesce((
    select
        public.qb_is_platform_admin()
        or exists (
            select 1
            from public.classes c
            where c.id = p_class_id
              and (
                    c.primary_teacher_id = public.qb_current_teacher_id()
                    or (
                        c.tenant_id is not null
                        and public.qb_can_manage_tenant(c.tenant_id)
                    )
                  )
        )),false);$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_current_student_id()') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_current_student_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select sp.id
    from public.student_profiles sp
    where sp.user_id = auth.uid()
    limit 1;
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_is_platform_admin()') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_is_platform_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
select auth.uid() is not null and exists (select 1 from public.profiles p where p.id = auth.uid() and lower(p.role::text) in ('admin', 'owner') and lower(p.status::text) = 'active')
$function$
$qb_bootstrap$; end if; end $boot$;

commit;
